const https = require('https');

const makeRequest = (path, method = 'GET', headers = {}) => {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'api.github.com',
      path: path,
      method: method,
      headers: {
        'User-Agent': 'Node.js',
        'Accept': 'application/vnd.github.v3+json',
        ...headers,
      },
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch {
          resolve({raw: data, status: res.statusCode});
        }
      });
    });

    req.on('error', reject);
    req.end();
  });
};

(async () => {
  try {
    // Get the commit status
    const commit = await makeRequest('/repos/re-cinq/HALEngine/commits/c618b2cb773899661ac15f8372f7e491e6b534cc/status');
    console.log('Commit status:', commit.state);
    console.log('Statuses:', JSON.stringify(commit.statuses, null, 2));
  } catch (e) {
    console.error('Error:', e.message);
  }
})();
EOF
